import{z as i,x as n,o as t,c as A,q as s,j as B,D as o,d as e,s as l,S as d,b as E}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"递归下降","description":"","frontmatter":{"title":"递归下降","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/recursive-descent.md","filePath":"cs/recursive-descent.md","lastUpdated":1791413859000}'),p={name:"cs/recursive-descent.md"};function c(h,a,m,C,D,u){const r=n("Mermaid");return t(),A("div",null,[a[2]||(a[2]=s('<h1 id="递归下降" tabindex="-1">递归下降 <a class="header-anchor" href="#递归下降" aria-label="Permalink to &quot;递归下降&quot;">​</a></h1><div class="epigraph"><p>每个非终结符一个函数；看当前记号决定用哪条产生式，再按右部依次匹配或递归。</p><footer>—— 据龙书第 4 章；递归下降作为 LL 的手工实现整理</footer></div><p>上一课<a href="/cs/ambiguity-leftrec">二义与左递归</a>给了产生式与推导树。本课不重定义 CFG。缺口是：<strong>分析器</strong>——从记号流建树。最直接的做法是最左推导的手工翻译：非终结符变成过程。本课只处理可递归下降的文法：无左递归、每次看一个记号能决定产生式。FIRST/FOLLOW 的系统计算下一课才写。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>文法在纸上，编译器要消费<a href="/cs/regex-lexer">词法</a>的流。递归下降：<code>parseE</code> 看 lookahead，选 \\(E\\to E+T\\) 或 \\(E\\to T\\)——但左递归会令 <code>parseE</code> 尚未读记号就再进 <code>parseE</code>，不停机。缺口先是<strong>改写左递归</strong>为右递归或循环，再写函数。预测失败则报语法错误。</p><p>这是 LL(1) 的直觉实现。本课用一记号前瞻，不写表驱动。</p><h3 id="左递归不是「递归」本身有罪" tabindex="-1">左递归不是「递归」本身有罪 <a class="header-anchor" href="#左递归不是「递归」本身有罪" aria-label="Permalink to &quot;左递归不是「递归」本身有罪&quot;">​</a></h3><p>右递归 \\(T\\to F*T\\) 对应函数末尾递归，可终止。左递归是「不消耗记号的自调用」。改写会改变结合性，要用循环恢复左结合，那是实现细节，本课点名。</p><p><span class="marginnote">龙书把递归下降当作教学分析器。错误恢复（恐慌模式跳到同步记号）本课只承认需要，不写完整策略。后课 LL 表是同一预测的表格化。</span></p><p><span class="marginnote">数字实例：以 \\(E\\to E+T\\mid T\\) 算 \\(1+2+3\\)。照原式写 <code>parseE</code>，它开头就要调 <code>parseE</code>，还没读进记号 <code>1</code> 就自我嵌套。改写成 \\(E\\to T\\,E&#39;\\)、\\(E&#39;\\to +\\,T\\,E&#39;\\mid\\varepsilon\\) 后，\\(E&#39;\\) 用 <code>while (lookahead == &#39;+&#39;)</code> 循环实现，\\(1+2+3\\) 自然解析成 \\((1+2)+3\\)，左结合保住。</span></p>',10)),(t(),B(d,null,{default:o(()=>[l(r,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20OLD%5B%22%E5%B7%A6%E9%80%92%E5%BD%92%E4%BA%A7%E7%94%9F%E5%BC%8F%20A%20%E2%86%92%20A%CE%B1%20%7C%20%CE%B2%22%5D%20--%3E%20CALL%5B%22parseA%20%E4%B8%80%E8%BF%9B%E5%B0%B1%E5%86%8D%E8%B0%83%20parseA%22%5D%0A%20%20CALL%20--%3E%20NOCON%5B%22%E6%B2%A1%E6%9C%89%E6%B6%88%E8%B4%B9%E4%BB%BB%E4%BD%95%E8%AE%B0%E5%8F%B7%22%5D%0A%20%20NOCON%20--%3E%20INF%5B%22%E6%97%A0%E9%99%90%E8%87%AA%E8%B0%83%E7%94%A8%EF%BC%8C%E6%A0%88%E7%88%86%22%5D%0A%20%20OLD%20--%3E%20FIX%5B%22%E6%B6%88%E9%99%A4%E7%9B%B4%E6%8E%A5%E5%B7%A6%E9%80%92%E5%BD%92%EF%BC%9AA%20%E2%86%92%20%CE%B2%20A%E2%80%B2%EF%BC%8CA%E2%80%B2%20%E2%86%92%20%CE%B1%20A%E2%80%B2%20%7C%20%CE%B5%22%5D%0A%20%20FIX%20--%3E%20LOOP%5B%22A%E2%80%B2%20%E7%94%A8%E5%BE%AA%E7%8E%AF%E5%90%83%20%CE%B1%EF%BC%8C%CE%B5%20%E6%94%B6%E5%B0%BE%22%5D%0A%20%20LOOP%20--%3E%20STOP%5B%22%E6%AF%8F%E8%BD%AE%E8%87%B3%E5%B0%91%E6%B6%88%E8%B4%B9%E4%B8%80%E4%B8%AA%E8%AE%B0%E5%8F%B7%EF%BC%8C%E5%BF%85%E7%84%B6%E7%BB%88%E6%AD%A2%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"方法",tabindex:"-1"},[e("方法 "),E("a",{class:"header-anchor",href:"#方法","aria-label":'Permalink to "方法"'},"​")],-1)),a[4]||(a[4]=E("p",null,[e("对每个 \\(A\\) 写 "),E("code",null,"parseA"),e("：按 lookahead 选产生式，右部终结符 "),E("code",null,"match"),e("，非终结符调用。建树：函数返回节点。消除直接左递归：\\(A\\to A\\alpha\\mid\\beta\\) 改为 \\(A\\to\\beta A'\\)，\\(A'\\to\\alpha A'\\mid\\varepsilon\\)。")],-1)),(t(),B(d,null,{default:o(()=>[l(r,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20TOK%5B%22%E5%BD%93%E5%89%8D%E8%AE%B0%E5%8F%B7%22%5D%20--%3E%20PRED%5B%22%E9%80%89%E4%BA%A7%E7%94%9F%E5%BC%8F%22%5D%0A%20%20PRED%20--%3E%20MATCH%5B%22%E5%8C%B9%E9%85%8D%E7%BB%88%E7%BB%93%E7%AC%A6%E6%88%96%E9%80%92%E5%BD%92%22%5D%0A%20%20MATCH%20--%3E%20NODE%5B%22%E8%BF%94%E5%9B%9E%E5%AD%90%E6%A0%91%22%5D%0A"})]),fallback:o(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=s('<p><a href="/cs/stack-adt">栈与调用</a>实现递归；深度与语法嵌套成正比，不是图的 DFS 边分类。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>每个函数的契约：从当前记号起消费 \\(A\\) 的一段，失败则诊断。公共前缀要用提取左因子，否则一个记号看不出选哪条——那已是 LL(1) 冲突，下一课命名。本课若手写时出现「两个分支同一记号」，就该改文法。</p><p>回溯（试一条失败再试另一条）可分析更大语言，最坏指数；主干不用。</p><p><span class="marginnote">术语翻译：提取左因子就是「把两条产生式相同的开头抽成一个公共前缀，剩下的差异留给下一个记号区分」。直觉类比：两条路前 100 米一模一样，就把前 100 米并成一条路，走到岔口再看路标选方向。</span></p><p><span class="marginnote">常见误区：初学者容易以为递归下降的「递归」会随输入变长而无限加深。实际调用深度只与语法<strong>嵌套</strong>成正比——\\(1+2+\\cdots+100\\) 这种左结合长链经改写后由循环消化，栈深是常数；真正会撑爆栈的是 <code>((((1))))</code> 这类深嵌套。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不算完整 FIRST/FOLLOW 集合算法。不处理 LR 的移进归约。不把表达式优先级用二十层非终结符写完——可用循环加优先级表，仍属下降族。后课默认：无左递归、可预测的文法有一份递归下降。系统化 FIRST/FOLLOW 与 LL(1) 表是下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>递归下降 = 最左推导的函数实现；一看一记号预测。</li><li>左递归必须改写；公共前缀要提取。</li><li>不用指数回溯。</li><li>出处：Aho et al., 龙书第 4 章。</li></ul>',10))])}const f=i(p,[["render",c]]);export{F as __pageData,f as default};
